import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import AdminPortalLayout from './AdminPortalLayout';
import { buildApiUrl } from '../../config/apiConfig';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import { isViewRoleProfile } from '../../utils/authRole';

interface PartnerApp {
  id: string;
  name: string;
  organizationType: string;
  organizationName?: string;
  scopes: string[];
  apiKeyMasked: string;
  isActive: boolean;
  lastUsedAt?: string;
  billingPlanId?: string;
  contractAnnualFeeInr?: number;
  rateLimitTier?: string;
  usageLimits?: {
    apiCallsPerMonth?: number;
    webhookEventsPerMonth?: number;
    reportPullsPerMonth?: number;
    msmeMonitoredPerYear?: number;
  };
  overageRates?: {
    perApiCallInr?: number;
    perWebhookInr?: number;
    perReportPullInr?: number;
    perMsmeMonthInr?: number;
  };
}

interface UsageQuota {
  metric: string;
  label: string;
  period: string;
  used: number;
  limit: number;
  percentUsed: number;
  exceeded: boolean;
}

interface PartnerUsageSummary {
  partner: PartnerApp;
  statistics: {
    monthToDate: { totalCalls: number; apiCalls?: number; distinctMsmeAccessed: number };
    yearToDate: { distinctMsmeAccessed: number };
  };
  quotas: UsageQuota[];
  billing: { estimatedTotalInr?: number; overage?: { estimatedOverageInr?: number } };
}

interface CatalogResponse {
  version: string;
  scopes: { id: string; description: string }[];
  endpoints: { method: string; path: string }[];
  openapiPath?: string;
  portalNote?: string;
}

const PARTNER_SCOPES = [
  'msme:read',
  'carbon:read',
  'reports:read',
  'transactions:summary',
  'webhooks:manage',
];

const authHeaders = () => ({
  Authorization: `Bearer ${localStorage.getItem('token')}`,
});

const PartnerIntegrationsAdmin: React.FC = () => {
  const isReviewer = isViewRoleProfile();
  const portalUser = getAdminPortalUser();
  const [catalog, setCatalog] = useState<CatalogResponse | null>(null);
  const [applications, setApplications] = useState<PartnerApp[]>([]);
  const [linkedCredential, setLinkedCredential] = useState<PartnerApp | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [createOpen, setCreateOpen] = useState(false);
  const [newKeyDialog, setNewKeyDialog] = useState<{
    apiKey: string;
    webhookSecret?: string;
    portalLogin?: { email: string };
  } | null>(null);
  const [usageDialog, setUsageDialog] = useState<PartnerUsageSummary | null>(null);
  const [limitsDialog, setLimitsDialog] = useState<PartnerApp | null>(null);
  const [limitsForm, setLimitsForm] = useState({
    rateLimitTier: 'standard',
    apiCallsPerMonth: 100000,
    webhookEventsPerMonth: 10000,
    reportPullsPerMonth: 2000,
    msmeMonitoredPerYear: 500,
    perApiCallInr: 0.15,
    perWebhookInr: 0.5,
    perReportPullInr: 5,
    perMsmeMonthInr: 25,
    contractAnnualFeeInr: 99000,
    billingPlanId: 'api_starter',
  });
  const [form, setForm] = useState({
    name: '',
    organizationName: portalUser?.accessCredentials?.organizationName || '',
    organizationType: 'integration_partner',
    contactEmail: portalUser?.email || '',
    scopes: ['msme:read', 'carbon:read'] as string[],
    billingPlanId: 'api_starter',
    contractAnnualFeeInr: 99000,
    portalLoginEmail: '',
    portalLoginPassword: '',
  });

  const loadCatalog = useCallback(async () => {
    const res = await axios.get(buildApiUrl('/partner-portal/catalog'), { headers: authHeaders() });
    setCatalog(res.data?.data || null);
  }, []);

  const loadApplications = useCallback(async () => {
    if (isReviewer) {
      const res = await axios.get(buildApiUrl('/partner-portal/my-credentials'), { headers: authHeaders() });
      const partner = res.data?.data?.partner;
      setLinkedCredential(partner || null);
      return;
    }
    const res = await axios.get(buildApiUrl('/partner-portal/applications'), { headers: authHeaders() });
    setApplications(res.data?.data?.applications || []);
  }, [isReviewer]);

  useEffect(() => {
    Promise.all([loadCatalog(), loadApplications()]).catch((err) => {
      setError(err?.response?.data?.message || err.message || 'Failed to load integrations');
    });
  }, [loadCatalog, loadApplications]);

  const handleCreate = async () => {
    try {
      const payload: Record<string, unknown> = {
        name: form.name,
        organizationName: form.organizationName,
        organizationType: form.organizationType,
        contactEmail: form.contactEmail,
        scopes: form.scopes,
        billingPlanId: form.billingPlanId,
        contractAnnualFeeInr: form.contractAnnualFeeInr,
      };
      if (form.portalLoginEmail && form.portalLoginPassword) {
        payload.portalLogin = {
          email: form.portalLoginEmail,
          password: form.portalLoginPassword,
          firstName: form.organizationName || form.name,
        };
      }

      const res = await axios.post(
        buildApiUrl('/partner-portal/applications'),
        payload,
        { headers: authHeaders() },
      );
      setNewKeyDialog({
        apiKey: res.data?.data?.apiKey,
        webhookSecret: res.data?.data?.webhookSecret,
        portalLogin: res.data?.data?.portalLogin,
      });
      setCreateOpen(false);
      await loadApplications();
    } catch (err: unknown) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to create application';
      setError(message);
    }
  };

  const handleRotate = async (id: string) => {
    try {
      const res = await axios.patch(
        buildApiUrl(`/partner-portal/applications/${id}`),
        { rotateApiKey: true },
        { headers: authHeaders() },
      );
      if (res.data?.data?.apiKey) {
        setNewKeyDialog({ apiKey: res.data.data.apiKey });
      }
      await loadApplications();
    } catch (err: unknown) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to rotate key';
      setError(message);
    }
  };

  const toggleActive = async (id: string, isActive: boolean) => {
    await axios.patch(
      buildApiUrl(`/partner-portal/applications/${id}`),
      { isActive: !isActive },
      { headers: authHeaders() },
    );
    await loadApplications();
  };

  const openUsage = async (id: string) => {
    try {
      const res = await axios.get(buildApiUrl(`/partner-portal/applications/${id}/usage`), {
        headers: authHeaders(),
      });
      setUsageDialog(res.data?.data || null);
    } catch (err: unknown) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to load partner usage';
      setError(message);
    }
  };

  const openLimits = (app: PartnerApp) => {
    setLimitsDialog(app);
    setLimitsForm({
      rateLimitTier: app.rateLimitTier || 'standard',
      apiCallsPerMonth: app.usageLimits?.apiCallsPerMonth ?? 100000,
      webhookEventsPerMonth: app.usageLimits?.webhookEventsPerMonth ?? 10000,
      reportPullsPerMonth: app.usageLimits?.reportPullsPerMonth ?? 2000,
      msmeMonitoredPerYear: app.usageLimits?.msmeMonitoredPerYear ?? 500,
      perApiCallInr: app.overageRates?.perApiCallInr ?? 0.15,
      perWebhookInr: app.overageRates?.perWebhookInr ?? 0.5,
      perReportPullInr: app.overageRates?.perReportPullInr ?? 5,
      perMsmeMonthInr: app.overageRates?.perMsmeMonthInr ?? 25,
      contractAnnualFeeInr: app.contractAnnualFeeInr ?? 99000,
      billingPlanId: app.billingPlanId || 'api_starter',
    });
  };

  const saveLimits = async () => {
    if (!limitsDialog) return;
    try {
      await axios.patch(
        buildApiUrl(`/partner-portal/applications/${limitsDialog.id}`),
        {
          rateLimitTier: limitsForm.rateLimitTier,
          billingPlanId: limitsForm.billingPlanId,
          contractAnnualFeeInr: limitsForm.contractAnnualFeeInr,
          usageLimits: {
            apiCallsPerMonth: limitsForm.apiCallsPerMonth,
            webhookEventsPerMonth: limitsForm.webhookEventsPerMonth,
            reportPullsPerMonth: limitsForm.reportPullsPerMonth,
            msmeMonitoredPerYear: limitsForm.msmeMonitoredPerYear,
          },
          overageRates: {
            perApiCallInr: limitsForm.perApiCallInr,
            perWebhookInr: limitsForm.perWebhookInr,
            perReportPullInr: limitsForm.perReportPullInr,
            perMsmeMonthInr: limitsForm.perMsmeMonthInr,
          },
        },
        { headers: authHeaders() },
      );
      setLimitsDialog(null);
      await loadApplications();
    } catch (err: unknown) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to update limits';
      setError(message);
    }
  };

  const activatePartnerBilling = async (id: string) => {
    try {
      await axios.patch(
        buildApiUrl(`/partner-portal/applications/${id}`),
        { activateBilling: true },
        { headers: authHeaders() },
      );
      await loadApplications();
    } catch (err: unknown) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to activate partner billing';
      setError(message);
    }
  };

  return (
    <AdminPortalLayout
      title="Integration APIs"
      subtitle="Partner credentials and public API reference for third-party companies"
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {catalog?.portalNote && (
        <Alert severity="info" sx={{ mb: 2 }}>
          {catalog.portalNote}
        </Alert>
      )}

      <Paper sx={{ p: 2, mb: 3 }}>
        <Typography variant="subtitle1" gutterBottom>
          Public developer reference
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Share the catalog with integration partners before issuing keys.
        </Typography>
        <Button
          variant="outlined"
          href="/partners"
          target="_blank"
          rel="noopener noreferrer"
        >
          Open /partners page
        </Button>
      </Paper>

      {isReviewer ? (
        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Your API credentials
          </Typography>
          {linkedCredential ? (
            <Stack spacing={1}>
              <Typography variant="body2">
                Application: <strong>{linkedCredential.name}</strong>
              </Typography>
              <Typography variant="body2">
                Key: <code>{linkedCredential.apiKeyMasked}</code>
              </Typography>
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                {linkedCredential.scopes.map((scope) => (
                  <Chip key={scope} label={scope} size="small" />
                ))}
              </Stack>
            </Stack>
          ) : (
            <Typography variant="body2" color="text.secondary">
              No API key is linked to this reviewer account yet. Contact your Carbon Intelligence administrator.
            </Typography>
          )}
        </Paper>
      ) : (
        <>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
            <Button variant="contained" onClick={() => setCreateOpen(true)}>
              Create partner application
            </Button>
          </Box>
          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Name</TableCell>
                  <TableCell>Organization</TableCell>
                  <TableCell>Scopes</TableCell>
                  <TableCell>Key</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {applications.map((app) => (
                  <TableRow key={app.id}>
                    <TableCell>{app.name}</TableCell>
                    <TableCell>{app.organizationName || app.organizationType}</TableCell>
                    <TableCell>
                      <Stack direction="row" spacing={0.5} flexWrap="wrap" useFlexGap>
                        {app.scopes.map((scope) => (
                          <Chip key={scope} label={scope} size="small" variant="outlined" />
                        ))}
                      </Stack>
                    </TableCell>
                    <TableCell>
                      <code>{app.apiKeyMasked}</code>
                    </TableCell>
                    <TableCell>
                      <Chip
                        size="small"
                        color={app.isActive ? 'success' : 'default'}
                        label={app.isActive ? 'Active' : 'Disabled'}
                      />
                    </TableCell>
                    <TableCell align="right">
                      <Stack direction="row" spacing={1} justifyContent="flex-end" flexWrap="wrap" useFlexGap>
                        <Button size="small" onClick={() => openUsage(app.id)}>
                          Usage
                        </Button>
                        <Button size="small" onClick={() => openLimits(app)}>
                          Limits
                        </Button>
                        <Button size="small" onClick={() => activatePartnerBilling(app.id)}>
                          Activate billing
                        </Button>
                        <Button size="small" onClick={() => handleRotate(app.id)}>
                          Rotate key
                        </Button>
                        <Button size="small" onClick={() => toggleActive(app.id, app.isActive)}>
                          {app.isActive ? 'Disable' : 'Enable'}
                        </Button>
                      </Stack>
                    </TableCell>
                  </TableRow>
                ))}
                {!applications.length && (
                  <TableRow>
                    <TableCell colSpan={6}>
                      <Typography variant="body2" color="text.secondary">
                        No partner applications yet.
                      </Typography>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </>
      )}

      <Dialog open={createOpen} onClose={() => setCreateOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Create partner application</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <TextField
              label="Application name"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
              fullWidth
              required
            />
            <TextField
              label="Organization name"
              value={form.organizationName}
              onChange={(e) => setForm((f) => ({ ...f, organizationName: e.target.value }))}
              fullWidth
            />
            <TextField
              label="Contact email"
              type="email"
              value={form.contactEmail}
              onChange={(e) => setForm((f) => ({ ...f, contactEmail: e.target.value }))}
              fullWidth
            />
            <FormControl fullWidth>
              <InputLabel>Organization type</InputLabel>
              <Select
                label="Organization type"
                value={form.organizationType}
                onChange={(e) => setForm((f) => ({ ...f, organizationType: e.target.value }))}
              >
                <MenuItem value="bank_incentives_partner">Bank / NBFC</MenuItem>
                <MenuItem value="government_accredited_auditor">Accredited auditor</MenuItem>
                <MenuItem value="verification_agency">Verification agency</MenuItem>
                <MenuItem value="integration_partner">Integration partner</MenuItem>
                <MenuItem value="other">Other</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Scopes</InputLabel>
              <Select
                multiple
                label="Scopes"
                value={form.scopes}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    scopes: typeof e.target.value === 'string' ? e.target.value.split(',') : e.target.value,
                  }))
                }
                renderValue={(selected) => (
                  <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                    {selected.map((value) => (
                      <Chip key={value} label={value} size="small" />
                    ))}
                  </Box>
                )}
              >
                {PARTNER_SCOPES.map((scope) => (
                  <MenuItem key={scope} value={scope}>
                    {scope}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              label="Billing plan ID"
              value={form.billingPlanId}
              onChange={(e) => setForm((f) => ({ ...f, billingPlanId: e.target.value }))}
              fullWidth
            />
            <TextField
              label="Contract annual fee (INR)"
              type="number"
              value={form.contractAnnualFeeInr}
              onChange={(e) => setForm((f) => ({ ...f, contractAnnualFeeInr: Number(e.target.value) }))}
              fullWidth
            />
            <Typography variant="subtitle2" sx={{ pt: 1 }}>
              Partner portal login (optional)
            </Typography>
            <TextField
              label="Portal email"
              type="email"
              value={form.portalLoginEmail}
              onChange={(e) => setForm((f) => ({ ...f, portalLoginEmail: e.target.value }))}
              fullWidth
            />
            <TextField
              label="Portal password"
              type="password"
              value={form.portalLoginPassword}
              onChange={(e) => setForm((f) => ({ ...f, portalLoginPassword: e.target.value }))}
              fullWidth
              helperText="Min. 6 characters. Partner signs in at /login to view usage and billing."
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleCreate} disabled={!form.name.trim()}>
            Create &amp; issue key
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={Boolean(newKeyDialog)} onClose={() => setNewKeyDialog(null)} maxWidth="sm" fullWidth>
        <DialogTitle>API key issued</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            Copy this key now. It will not be shown again.
          </Alert>
          {newKeyDialog && (
            <Stack spacing={2}>
              <TextField
                label="API key"
                value={newKeyDialog.apiKey}
                fullWidth
                InputProps={{ readOnly: true }}
                multiline
              />
              {newKeyDialog.webhookSecret && (
                <TextField
                  label="Webhook secret"
                  value={newKeyDialog.webhookSecret}
                  fullWidth
                  InputProps={{ readOnly: true }}
                />
              )}
              {newKeyDialog.portalLogin?.email && (
                <Alert severity="success">
                  Portal login created: {newKeyDialog.portalLogin.email} — sign in at /login
                </Alert>
              )}
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button variant="contained" onClick={() => setNewKeyDialog(null)}>
            Done
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={Boolean(usageDialog)} onClose={() => setUsageDialog(null)} maxWidth="md" fullWidth>
        <DialogTitle>Partner usage &amp; billing</DialogTitle>
        <DialogContent>
          {usageDialog && (
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Typography variant="body2">
                Application: <strong>{usageDialog.partner.name}</strong>
              </Typography>
              <Typography variant="body2" color="text.secondary">
                MTD API calls: {usageDialog.statistics.monthToDate.apiCalls ?? usageDialog.statistics.monthToDate.totalCalls}
                {' · '}
                MSMEs YTD: {usageDialog.statistics.yearToDate.distinctMsmeAccessed}
              </Typography>
              <Typography variant="subtitle2">Quotas</Typography>
              {usageDialog.quotas.map((quota) => (
                <Box key={quota.metric} sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Typography variant="body2">
                    {quota.label} ({quota.period})
                  </Typography>
                  <Typography variant="body2" color={quota.exceeded ? 'error.main' : 'text.secondary'}>
                    {quota.used} / {quota.limit}
                  </Typography>
                </Box>
              ))}
              <Typography variant="subtitle2">Indicative billing (month)</Typography>
              <Typography variant="body2">
                Estimated total: ₹{usageDialog.billing.estimatedTotalInr ?? 0}
                {' '}(overage ₹{usageDialog.billing.overage?.estimatedOverageInr ?? 0})
              </Typography>
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setUsageDialog(null)}>Close</Button>
        </DialogActions>
      </Dialog>

      <Dialog open={Boolean(limitsDialog)} onClose={() => setLimitsDialog(null)} maxWidth="sm" fullWidth>
        <DialogTitle>Usage limits &amp; overage rates</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <FormControl fullWidth>
              <InputLabel>Rate limit tier</InputLabel>
              <Select
                label="Rate limit tier"
                value={limitsForm.rateLimitTier}
                onChange={(e) => setLimitsForm((f) => ({ ...f, rateLimitTier: e.target.value }))}
              >
                <MenuItem value="standard">Standard (60 req/min)</MenuItem>
                <MenuItem value="elevated">Elevated (300 req/min)</MenuItem>
              </Select>
            </FormControl>
            <TextField
              label="API calls / month"
              type="number"
              value={limitsForm.apiCallsPerMonth}
              onChange={(e) => setLimitsForm((f) => ({ ...f, apiCallsPerMonth: Number(e.target.value) }))}
              fullWidth
            />
            <TextField
              label="Webhook events / month"
              type="number"
              value={limitsForm.webhookEventsPerMonth}
              onChange={(e) => setLimitsForm((f) => ({ ...f, webhookEventsPerMonth: Number(e.target.value) }))}
              fullWidth
            />
            <TextField
              label="Report pulls / month"
              type="number"
              value={limitsForm.reportPullsPerMonth}
              onChange={(e) => setLimitsForm((f) => ({ ...f, reportPullsPerMonth: Number(e.target.value) }))}
              fullWidth
            />
            <TextField
              label="MSMEs monitored / year"
              type="number"
              value={limitsForm.msmeMonitoredPerYear}
              onChange={(e) => setLimitsForm((f) => ({ ...f, msmeMonitoredPerYear: Number(e.target.value) }))}
              fullWidth
            />
            <TextField
              label="Overage: ₹ / API call"
              type="number"
              inputProps={{ step: 0.01 }}
              value={limitsForm.perApiCallInr}
              onChange={(e) => setLimitsForm((f) => ({ ...f, perApiCallInr: Number(e.target.value) }))}
              fullWidth
            />
            <TextField
              label="Contract annual fee (INR)"
              type="number"
              value={limitsForm.contractAnnualFeeInr}
              onChange={(e) => setLimitsForm((f) => ({ ...f, contractAnnualFeeInr: Number(e.target.value) }))}
              fullWidth
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setLimitsDialog(null)}>Cancel</Button>
          <Button variant="contained" onClick={saveLimits}>
            Save limits
          </Button>
        </DialogActions>
      </Dialog>
    </AdminPortalLayout>
  );
};

export default PartnerIntegrationsAdmin;
